import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import CommunityPage from './CommunityPage';
import GroupFlair from './GroupFlair';
import { communityGroups, groupsEnabled, groupSlug, groupUrl, memberCount } from './groups';
import { t } from '../../utils/settings';

/**
 * A lista de grupos (/g): um cartão por grupo, com o símbolo, o
 * nome e quantos membros tem.
 *
 * Os grupos já vêm no payload do fórum — só os que o ator pode ver —, então a
 * página não faz requisição nenhuma.
 */
export default class GroupsPage extends CommunityPage {
  title() {
    return t('community.groups.title');
  }
  className() {
    return 'CanelaGroupsPage';
  }
  enabled() {
    return groupsEnabled();
  }

  /** O filtro por nome do topo (`groups-header-filters`), só no navegador. */
  filter = '';
  content() {
    const query = this.filter.trim().toLowerCase();
    const groups = communityGroups().filter(group => !query || [group.namePlural(), group.nameSingular(), groupSlug(group)].some(name => (name || '').toLowerCase().includes(query)));
    return m("div", {
      className: "CanelaGroups"
    }, m("h1", {
      className: "sr-only"
    }, t('community.groups.title')), m("div", {
      className: "CanelaGroups-header"
    }, m("input", {
      className: "FormControl CanelaGroups-filter",
      type: "search",
      placeholder: t('community.groups.filter_placeholder'),
      "aria-label": t('community.groups.filter_placeholder'),
      value: this.filter,
      oninput: event => this.filter = event.target.value
    })), groups.length ? m("ul", {
      className: "CanelaGroups-grid"
    }, groups.map(group => this.card(group))) : m("p", {
      className: "CanelaCommunity-empty"
    }, t('community.groups.empty')));
  }

  /**
   * O cartão do grupo: o flair redondo, o nome grande com o
   * @endereço embaixo, os membros no canto e, no pé, a situação de entrada —
   * no Flarum só a administração põe gente nos grupos, então todos são
   * "Fechado".
   */
  card(group) {
    const count = memberCount(group);
    return m("li", {
      key: group.id(),
      className: "CanelaGroups-item"
    }, m(Link, {
      className: "CanelaGroupCard",
      href: groupUrl(group),
      style: group.color() ? {
        '--group-color': group.color()
      } : undefined
    }, m("span", {
      className: "CanelaGroupCard-inner"
    }, m("span", {
      className: "CanelaGroupCard-infoWrapper"
    }, group.icon() && m(GroupFlair, {
      group: group
    }), m("span", {
      className: "CanelaGroupCard-info"
    }, m("span", {
      className: "CanelaGroupCard-details"
    }, m("span", {
      className: "CanelaGroupCard-name"
    }, group.namePlural()), m("span", {
      className: "CanelaGroupCard-mention"
    }, "@", groupSlug(group))), count !== null && m("span", {
      className: "CanelaGroupCard-count",
      title: t('community.groups.members', {
        count
      })
    }, m(Icon, {
      name: "far fa-user"
    }), count))), m("span", {
      className: "CanelaGroupCard-membership"
    }, group.isHidden() ? m("span", {
      className: "CanelaGroupCard-hidden"
    }, m(Icon, {
      name: "far fa-eye-slash"
    }), " ", t('community.groups.hidden')) : m("span", null, m(Icon, {
      name: "fas fa-ban"
    }), " ", t('community.groups.closed'))))));
  }
}
flarum.reg.add('ramon-canela', 'forum/features/community/GroupsPage', GroupsPage);